<?php
$editId = filter_var($_GET['edit'] ?? 0, FILTER_VALIDATE_INT) ?: 0;
$services = db()->query('SELECT * FROM laundry__services_tbl ORDER BY is_active DESC, id DESC')->fetchAll();
$editing = null;
foreach ($services as $service) if ((int)$service['id'] === $editId) $editing = $service;
?>
<div class="page-heading"><div><p class="eyebrow">🫧 จัดการบริการ</p><h1>บริการ · ราคา</h1><p>เพิ่ม แก้ไข หรือปิดบริการ</p></div></div>
<div class="two-col"><section class="panel"><div class="panel-header"><h2>🫧 บริการทั้งหมด</h2><span class="pill"><?= count($services) ?> รายการ</span></div><div class="table-wrap"><table><thead><tr><th>บริการ</th><th>ราคา</th><th>สถานะ</th><th>จัดการ</th></tr></thead><tbody>
<?php foreach ($services as $s): ?><tr><td><strong><?= e($s['name']) ?></strong><small class="table-muted">ต่อ <?= e($s['unit']) ?></small></td><td>฿<?= money($s['price']) ?></td><td><span class="status <?= $s['is_active'] ? 'is-good' : 'is-muted' ?>"><?= $s['is_active'] ? 'เปิดใช้งาน' : 'ปิดใช้งาน' ?></span></td><td><div class="row-actions"><a class="text-link" href="<?= e(url('services', ['edit' => (int)$s['id']])) ?>">แก้ไข</a><form method="post" action="index.php" class="inline-form"><?= csrf_field() ?><input type="hidden" name="action" value="<?= $s['is_active'] ? 'service-archive' : 'service-restore' ?>"><input type="hidden" name="id" value="<?= (int)$s['id'] ?>"><button type="submit" class="text-button"><?= $s['is_active'] ? 'ปิด' : 'เปิด' ?></button></form></div></td></tr><?php endforeach; ?>
<?php if (!$services): ?><tr><td colspan="4" class="empty-cell">ยังไม่มีบริการ</td></tr><?php endif; ?></tbody></table></div></section>
<section class="panel"><div class="panel-header"><h2><?= $editing ? '✏️ แก้ไขบริการ' : '➕ เพิ่มบริการ' ?></h2><?php if ($editing): ?><a class="text-link" href="<?= e(url('services')) ?>">ยกเลิกแก้ไข</a><?php endif; ?></div><form method="post" action="index.php" class="form-stack form-spaced"><?= csrf_field() ?><input type="hidden" name="action" value="service-save"><input type="hidden" name="id" value="<?= (int)($editing['id'] ?? 0) ?>"><label>ชื่อบริการ<input name="name" required maxlength="100" placeholder="เช่น ซักอบ" value="<?= e($editing['name'] ?? '') ?>"></label><label>หน่วยคิดราคา<input name="unit" required maxlength="20" placeholder="เช่น กก. / ตัว / ผืน" value="<?= e($editing['unit'] ?? '') ?>"></label><label>ราคา (บาท)<input name="price" type="number" step="0.01" min="0" max="99999999" required value="<?= e((string)($editing['price'] ?? '')) ?>"></label><button type="submit" class="btn btn-primary btn-block">💾 บันทึก</button></form></section></div>
